"""Pydantic schemas for ValidationIssue records and validation pipeline results."""

from datetime import datetime
from pydantic import BaseModel, ConfigDict, Field

from app.models.validation_issue import ValidationSeverity


class ValidationIssueItem(BaseModel):
    """Represents an issue generated by a validation rule."""

    rule: str = Field(..., description="Unique machine identifier for the violated rule")
    severity: ValidationSeverity = Field(..., description="Issue severity (info, warning, error)")
    message: str = Field(..., description="Human-readable description of the issue")


class ValidationIssueRead(ValidationIssueItem):
    """Public read schema for a persisted validation issue."""

    model_config = ConfigDict(from_attributes=True)

    id: int
    observation_id: int
    created_at: datetime


class ObservationValidationSummary(BaseModel):
    """Summary of validation evaluation for an observation."""

    observation_id: int
    is_valid: bool = Field(
        ...,
        description="True if the observation has zero 'error'-severity issues (eligible for estimation)",
    )
    excluded_from_estimation: bool = Field(
        default=False,
        description="True if any error-severity validation issue exists, excluding this observation from carbon estimation",
    )
    error_count: int = Field(default=0)
    warning_count: int = Field(default=0)
    info_count: int = Field(default=0)
    issues: list[ValidationIssueRead]
